"""Second question types for Linear Algebra (LA): every single-type objective gets a reverse, a neighbouring quantity or a
structural question, verified with sympy's Matrix routines."""
from opl_dsl import Q

FILE, FRAMEWORK = "la-second-types", "linear-algebra"
MC = ["{{o1}}", "{{o2}}", "{{o3}}", "{{o4}}"]
I2 = "Matrix([[a, b], [c, d]])"


def facts(name, skill, rows, explain):
    return Q(name, skill, "{{q}}", pace="recall", cases=[{"q": q, "o1": a, "o2": b, "o3": c, "o4": d} for q, a, b, c, d in rows],
             choice=MC, correct="0", verify="authored", explain=explain)


